
def findFloors(floors):
    level = 0
    basement = -1

    for i, c in enumerate(floors):
        if c == "(":
            level += 1
        elif c == ")":
            level -= 1

        if level == -1 & basement == -1:
            basement = i + 1

    return (level, basement)

